import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        st = new StringTokenizer(br.readLine());
        int[] l = new int[n];
        for (int i = 0; i < n; i++) {
            l[i] = Integer.parseInt(st.nextToken());
        }
        int[] first = Arrays.copyOfRange(l, 0, n / 2);
        int[] sec = Arrays.copyOfRange(l, n / 2, n);
        int n1 = n / 2;
        int n2 = n / 2 + n % 2;
        int t1 = 1 << n1;
        int t2 = 1 << n2;
        List<Integer> s1 = new ArrayList<>();
        for (int i = 0; i < t1; i++) {
            int now = 0;
            for (int j = 0; j < first.length; j++) {
                if ((i & (1 << j)) != 0) {
                    now += first[j];
                }
            }
            s1.add(now % m);
        }
        List<Integer> s2 = new ArrayList<>();
        for (int i = 0; i < t2; i++) {
            int now = 0;
            for (int j = 0; j < sec.length; j++) {
                if ((i & (1 << j)) != 0) {
                    now += sec[j];
                }
            }
            s2.add(now % m);
        }
        Collections.sort(s1);
        Collections.sort(s2);
        int maxi = 0;

        // Helper function for binary search
        class Helper {
            int check(List<Integer> list, int x) {
                int lo = 0;
                int hi = list.size() - 1;
                int ans = 0;
                while (lo <= hi) {
                    int mi = (lo + hi) >> 1;
                    if (list.get(mi) < x) {
                        ans = list.get(mi);
                        lo = mi + 1;
                    } else {
                        hi = mi - 1;
                    }
                }
                return ans;
            }
        }
        Helper helper = new Helper();

        for (int i : s1) {
            int req = m - i;
            int pair = helper.check(s2, req);
            int current = (i + pair) % m;
            if (current > maxi) {
                maxi = current;
            }
        }
        System.out.println(maxi);
    }
}
